import Foundation

/// One short health fact, in Vietnamese and English. The first ~100 come from
/// the Tauri app's `facts.rs` (same product, same voice); the rest were written
/// for the macOS port in the same style: short, concrete numbers, cited when known.
public struct HealthQuote: Sendable, Equatable, Hashable {
    public let emoji: String
    public let vi: String
    public let en: String

    public init(_ emoji: String, _ vi: String, _ en: String) {
        self.emoji = emoji
        self.vi = vi
        self.en = en
    }

    public func text(in language: AppLanguage) -> String {
        switch language {
        case .vietnamese: return vi
        case .english: return en
        }
    }
}

private func quote(_ emoji: String, _ vi: String, _ en: String) -> HealthQuote {
    HealthQuote(emoji, vi, en)
}

